import React from 'react'
import Contacts from './Contacts'

const Home = () => {
  return (
    <div style={{
        textAlign: 'center',
        height: "200px",
        width: '2000px'
            }}>
      <h1>Hi, my name is John Doe</h1>
      <h1>a frontend developer</h1>
      <h1>with passion for learning and creating.</h1>
      <img src="./header-bg.jpg" alt="Profile" />  

    <button onClick={() => window.open("/CV.pdf")}>Download CV</button>

    </div>
  )
}

export default Home
